seen = {}


@kt.kernel
def k(x=kt.In(16, 32), y=kt.Out(16, 32)):
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(1):
            r = (c + t) * 4 + 1
            seen["r"] = [
                type(r).__name__,
                r.const,
                sorted([a.text(), v] for a, v in r.terms.items()),
            ]
            kt.store(y[r - 1 : r + 3, :], kt.load(x[r - 1 : r + 3, :]))


def facts():
    k.trace({"x": TY.TensorSpec.make((16, 32))}, machine=MACHINE)
    return seen
